from abc import ABCMeta, abstractmethod

from enum import Enum, unique
import six
from typing import Optional  # noqa: F401


@unique
class ALDTypes(Enum):
    RET = 'RET'
    MRET = 'MRET'
    MHA = 'MHA'
    RAE = 'RAE'
    EMU = 'EMU'


@six.add_metaclass(ABCMeta)
class ALD(object):

    @abstractmethod
    def __init__(self, model=None, serial_number=None, aisg_protocol='2.0', ald_type=None, vendor=None):
        # type: (Optional[str], Optional[str], Optional[str], Optional[str], Optional[str]) -> None
        """
        Antenna Line Device

        :param Optional[str] model: model
        :param Optional[str] serial_number: serial_number
        :param Optional[str] aisg_protocol: aisg protocol
        :param Optional[str] ald_type: str type (unique identifier) of the ald type,
        should be one of ALDTypes' attributes
        :param Optional[str] vendor: vendor Name of the manufacturer
        """

        self.model = model
        self.serial_number = serial_number
        self.aisg_protocol = aisg_protocol
        self.ald_type = ald_type
        self.vendor = vendor


class TongYu(ALD):
    def __init__(self, **kwargs):
        super(TongYu, self).__init__(**kwargs)
        self.vendor = "TONGYU"


class KA_RCU(ALD):
    """
    Kathrein Remote Control Unit.

    :param [str] serial_number: serial_number
    :param [str] aisg_protocol: aisg_protocol
    :param [int] antenna_id: Unique identifier of the antenna port,
        e.g in NIDD either ANTL.antPortId or, for mMiMo, PHYANT.phyAntId
    """
    def __init__(self, **kwargs):
        super(KA_RCU, self).__init__(
            serial_number=kwargs.get("serial_number", None),
            aisg_protocol=kwargs.get("aisg_protocol", "2.0"),
            model="HW_V_A00",
            vendor="KATHREIN",
        )
        self.antenna_id = kwargs.get("antenna_id", None),
        self.product_code = "86010148"
        self.ald_type = ALDTypes.RET


class ALDEmulator(ALD):
    def __init__(self, **kwargs):
        """
        ALD Emulator

        :param [int] configuration_port: configuration_port
        :param [str] ip_address: ip_address
        :param [int] ip_port: int ip_port
        :param [str] com_port: str com_port
        :param [str] antenna_line_name: str antenna_line_name
        """
        self.ald_type = ALDTypes.EMU
        self.vendor = "Nokia"
        self.serial_number = kwargs.get("serial_number", None)
        self.configuration_port = kwargs.get("configuration_port", 1)
        self.ip_address = kwargs.get("ip_address")
        self.ip_port = kwargs.get("ip_port")
        self.com_port = kwargs.get("com_port")
        self.antenna_line_name = kwargs.get("antenna_line_name")
        self.connections = [
            {
                "antline_dc_port": self.configuration_port,
                "antline_data_port": self.configuration_port
            },
            {
                "antline_dc_port": self.configuration_port,
                "antline_data_port": self.configuration_port + 1
            }
        ]
